type package=Copy|Fill_mipmap|Access_counter|Optimize|Indirect_reset|Counter_sample|Synchronize|Fence
type item={id:string;package:package;operation:string;tests:string list}
let contains s n=let l=String.length n in let rec f i=i+l<=String.length s&&(String.sub s i l=n||f(i+1))in f 0
let classify id=let package,operation,tests=if contains id " copy"then Copy,"Metal.Blit_encoder.copy",["same-device exact kinds";"region/stride/offset bounds";"source/destination completion retention"]else if contains id "fillBuffer"||contains id "generateMipmaps"then Fill_mipmap,"Metal.Blit_encoder.fill/generate_mipmaps",["range/value validation";"format/mipmap capability"]else if contains id "TextureAccessCounters"then Access_counter,"Metal.Blit_encoder texture access counters",["region/level/slice bounds";"counter buffer length"]else if contains id "optimize"then Optimize,"Metal.Blit_encoder.optimize",["platform availability";"resource range/state"]else if contains id "resetCommands"then Indirect_reset,"Metal.Blit_encoder.reset_indirect",["command range bounds";"indirect-buffer retention"]else if contains id "Counters"||contains id "sampleCounters"then Counter_sample,"Metal.Blit_encoder counters",["sample index/range";"destination buffer bounds"]else if contains id "synchronize"then Synchronize,"Metal.Blit_encoder.synchronize",["managed-storage capability";"slice/level bounds"]else Fence,"Metal.Blit_encoder fence",["same-device fence";"completion lifetime"]in{id;package;operation;tests}
let validate items=let count p=List.length(List.filter(fun x->x.package=p)items)in if List.length items<>25||List.map count[Copy;Fill_mipmap;Access_counter;Optimize;Indirect_reset;Counter_sample;Synchronize;Fence]<>[9;2;2;5;1;2;2;2]||List.exists(fun x->x.operation=""||x.tests=[])items then failwith"BlitCommand25 tail drift"
